// ServerInterface represents all server handlers.
type ServerInterface interface {
	// InspectAccountToken What a one-time invite / password-reset link is for (no sign-in required)
	// (GET /account-tokens/{token})
	InspectAccountToken(w http.ResponseWriter, r *http.Request, token string)
	// AcceptAccountToken Set the password (and name, for invitations) using a one-time link
	// (POST /account-tokens/{token})
	AcceptAccountToken(w http.ResponseWriter, r *http.Request, token string)
	// ListSystemAudit System-level audit events without an organization (system admin), newest first
	// (GET /admin/audit)
	ListSystemAudit(w http.ResponseWriter, r *http.Request, params ListSystemAuditParams)
	// AdminListOrganizations All organizations (system admin)
	// (GET /admin/organizations)
	AdminListOrganizations(w http.ResponseWriter, r *http.Request)
	// AdminCreateOrganization Create an organization (system admin)
	// (POST /admin/organizations)
	AdminCreateOrganization(w http.ResponseWriter, r *http.Request, params AdminCreateOrganizationParams)
	// AdminDeleteOrganization Soft-delete an organization (system admin, ADR-022)
	// (DELETE /admin/organizations/{orgId})
	AdminDeleteOrganization(w http.ResponseWriter, r *http.Request, orgId OrgId, params AdminDeleteOrganizationParams)
	// AdminListUsers All users (system admin)
	// (GET /admin/users)
	AdminListUsers(w http.ResponseWriter, r *http.Request)
	// AdminDisableUser Disable a user (soft delete, signs them out everywhere)
	// (POST /admin/users/{userId}/disable)
	AdminDisableUser(w http.ResponseWriter, r *http.Request, userId UserId, params AdminDisableUserParams)
	// AdminEnableUser Re-enable a disabled user
	// (POST /admin/users/{userId}/enable)
	AdminEnableUser(w http.ResponseWriter, r *http.Request, userId UserId, params AdminEnableUserParams)
	// AdminCreatePasswordReset Issue a one-time password-reset link (24 h)
	// (POST /admin/users/{userId}/password-reset)
	AdminCreatePasswordReset(w http.ResponseWriter, r *http.Request, userId UserId, params AdminCreatePasswordResetParams)
	// AdminResetMfa Remove MFA so the user can enroll again (lost phone and recovery codes)
	// (POST /admin/users/{userId}/reset-mfa)
	AdminResetMfa(w http.ResponseWriter, r *http.Request, userId UserId, params AdminResetMfaParams)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Sign out and clear the session cookie
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request, params LogoutParams)
	// GetCurrentSession Current user and CSRF token
	// (GET /auth/me)
	GetCurrentSession(w http.ResponseWriter, r *http.Request)
	// DisableMfa Turn off MFA (not allowed when MFA is mandatory for the account)
	// (POST /auth/mfa/disable)
	DisableMfa(w http.ResponseWriter, r *http.Request, params DisableMfaParams)
	// EnableMfa Confirm enrollment with a code; returns one-time recovery codes
	// (POST /auth/mfa/enable)
	EnableMfa(w http.ResponseWriter, r *http.Request, params EnableMfaParams)
	// SetupMfa Start TOTP enrollment (returns the secret and a QR code once)
	// (POST /auth/mfa/setup)
	SetupMfa(w http.ResponseWriter, r *http.Request, params SetupMfaParams)
	// VerifyMfa Complete sign-in with a TOTP code or a recovery code
	// (POST /auth/mfa/verify)
	VerifyMfa(w http.ResponseWriter, r *http.Request, params VerifyMfaParams)
	// GetHealthz Liveness + database check
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// ListMyOrganizations Organizations the current user belongs to
	// (GET /orgs)
	ListMyOrganizations(w http.ResponseWriter, r *http.Request)
	// GetOrganization Organization details and the caller's membership
	// (GET /orgs/{orgId})
	GetOrganization(w http.ResponseWriter, r *http.Request, orgId OrgId)
	// UpdateOrganization Rename / edit notes (owner, admin). Optimistic lock on version.
	// (PATCH /orgs/{orgId})
	UpdateOrganization(w http.ResponseWriter, r *http.Request, orgId OrgId, params UpdateOrganizationParams)
	// ActivateOrganization Remember this organization as the default to open after sign-in
	// (POST /orgs/{orgId}/activate)
	ActivateOrganization(w http.ResponseWriter, r *http.Request, orgId OrgId, params ActivateOrganizationParams)
	// ListOrgAudit Audit log of the organization (owner/admin), newest first
	// (GET /orgs/{orgId}/audit)
	ListOrgAudit(w http.ResponseWriter, r *http.Request, orgId OrgId, params ListOrgAuditParams)
	// ListBusinessUnits Business units of the organization, each under a partner (ADR-031)
	// (GET /orgs/{orgId}/business-units)
	ListBusinessUnits(w http.ResponseWriter, r *http.Request, orgId OrgId, params ListBusinessUnitsParams)
	// CreateBusinessUnit Create a unit under a partner (owner/admin)
	// (POST /orgs/{orgId}/business-units)
	CreateBusinessUnit(w http.ResponseWriter, r *http.Request, orgId OrgId, params CreateBusinessUnitParams)
	// DeleteBusinessUnit Soft-delete a unit without live sites (owner/admin)
	// (DELETE /orgs/{orgId}/business-units/{businessUnitId})
	DeleteBusinessUnit(w http.ResponseWriter, r *http.Request, orgId OrgId, businessUnitId BusinessUnitId, params DeleteBusinessUnitParams)
	// GetBusinessUnit One business unit
	// (GET /orgs/{orgId}/business-units/{businessUnitId})
	GetBusinessUnit(w http.ResponseWriter, r *http.Request, orgId OrgId, businessUnitId BusinessUnitId)
	// UpdateBusinessUnit Edit a unit (its partner cannot change)
	// (PATCH /orgs/{orgId}/business-units/{businessUnitId})
	UpdateBusinessUnit(w http.ResponseWriter, r *http.Request, orgId OrgId, businessUnitId BusinessUnitId, params UpdateBusinessUnitParams)
	// ListMembers Members of the organization
	// (GET /orgs/{orgId}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, orgId OrgId)
	// AddMember Add a member by email (owner/admin/user.manage); unknown emails get a one-time invite link
	// (POST /orgs/{orgId}/members)
	AddMember(w http.ResponseWriter, r *http.Request, orgId OrgId, params AddMemberParams)
	// RemoveMember Remove a member from the organization (the last owner cannot be removed)
	// (DELETE /orgs/{orgId}/members/{userId})
	RemoveMember(w http.ResponseWriter, r *http.Request, orgId OrgId, userId UserId, params RemoveMemberParams)
	// UpdateMember Change role / extra permissions (optimistic lock on version)
	// (PATCH /orgs/{orgId}/members/{userId})
	UpdateMember(w http.ResponseWriter, r *http.Request, orgId OrgId, userId UserId, params UpdateMemberParams)
	// RegenerateInvite Issue a new invite link for a member who has not accepted yet (old links stop working)
	// (POST /orgs/{orgId}/members/{userId}/invite)
	RegenerateInvite(w http.ResponseWriter, r *http.Request, orgId OrgId, userId UserId, params RegenerateInviteParams)
	// ListPartners Partners of the organization (ADR-031)
	// (GET /orgs/{orgId}/partners)
	ListPartners(w http.ResponseWriter, r *http.Request, orgId OrgId)
	// CreatePartner Create a partner (owner/admin)
	// (POST /orgs/{orgId}/partners)
	CreatePartner(w http.ResponseWriter, r *http.Request, orgId OrgId, params CreatePartnerParams)
	// DeletePartner Soft-delete a partner without live units (owner/admin)
	// (DELETE /orgs/{orgId}/partners/{partnerId})
	DeletePartner(w http.ResponseWriter, r *http.Request, orgId OrgId, partnerId PartnerId, params DeletePartnerParams)
	// GetPartner One partner
	// (GET /orgs/{orgId}/partners/{partnerId})
	GetPartner(w http.ResponseWriter, r *http.Request, orgId OrgId, partnerId PartnerId)
	// UpdatePartner Edit a partner; a code change renames the prefix of its site codes (ADR-030/031)
	// (PATCH /orgs/{orgId}/partners/{partnerId})
	UpdatePartner(w http.ResponseWriter, r *http.Request, orgId OrgId, partnerId PartnerId, params UpdatePartnerParams)
	// ListSites Sites of the organization (filtered by the member site scope)
	// (GET /orgs/{orgId}/sites)
	ListSites(w http.ResponseWriter, r *http.Request, orgId OrgId, params ListSitesParams)
	// CreateSite Create a site (owner/admin/editor without a site scope)
	// (POST /orgs/{orgId}/sites)
	CreateSite(w http.ResponseWriter, r *http.Request, orgId OrgId, params CreateSiteParams)
	// SuggestSiteCode Next free site code for a partner and place (ADR-030/031)
	// (GET /orgs/{orgId}/sites/next-code)
	SuggestSiteCode(w http.ResponseWriter, r *http.Request, orgId OrgId, params SuggestSiteCodeParams)
	// DeleteSite Soft-delete a site (owner/admin)
	// (DELETE /orgs/{orgId}/sites/{siteId})
	DeleteSite(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, params DeleteSiteParams)
	// GetSite One site
	// (GET /orgs/{orgId}/sites/{siteId})
	GetSite(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId)
	// UpdateSite Edit a site (optimistic lock on version)
	// (PATCH /orgs/{orgId}/sites/{siteId})
	UpdateSite(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, params UpdateSiteParams)
	// ListLocations Location tree of the site as a flat list (parentId links)
	// (GET /orgs/{orgId}/sites/{siteId}/locations)
	ListLocations(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId)
	// CreateLocation Add a building, floor or room
	// (POST /orgs/{orgId}/sites/{siteId}/locations)
	CreateLocation(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, params CreateLocationParams)
	// DeleteLocation Delete an empty location (409 while it has children or racks)
	// (DELETE /orgs/{orgId}/sites/{siteId}/locations/{locationId})
	DeleteLocation(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, locationId LocationId, params DeleteLocationParams)
	// UpdateLocation Rename / reorder a location
	// (PATCH /orgs/{orgId}/sites/{siteId}/locations/{locationId})
	UpdateLocation(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, locationId LocationId, params UpdateLocationParams)
	// ListRacks Racks of the site
	// (GET /orgs/{orgId}/sites/{siteId}/racks)
	ListRacks(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId)
	// CreateRack Add a rack to a location of the site
	// (POST /orgs/{orgId}/sites/{siteId}/racks)
	CreateRack(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, params CreateRackParams)
	// DeleteRack Delete an empty rack
	// (DELETE /orgs/{orgId}/sites/{siteId}/racks/{rackId})
	DeleteRack(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, rackId RackId, params DeleteRackParams)
	// UpdateRack Edit / move a rack within the site
	// (PATCH /orgs/{orgId}/sites/{siteId}/racks/{rackId})
	UpdateRack(w http.ResponseWriter, r *http.Request, orgId OrgId, siteId SiteId, rackId RackId, params UpdateRackParams)
}

