// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// InspectAccountToken What a one-time invite / password-reset link is for (no sign-in required)
	// (GET /account-tokens/{token})
	InspectAccountToken(ctx context.Context, request InspectAccountTokenRequestObject) (InspectAccountTokenResponseObject, error)
	// AcceptAccountToken Set the password (and name, for invitations) using a one-time link
	// (POST /account-tokens/{token})
	AcceptAccountToken(ctx context.Context, request AcceptAccountTokenRequestObject) (AcceptAccountTokenResponseObject, error)
	// ListSystemAudit System-level audit events without an organization (system admin), newest first
	// (GET /admin/audit)
	ListSystemAudit(ctx context.Context, request ListSystemAuditRequestObject) (ListSystemAuditResponseObject, error)
	// AdminListOrganizations All organizations (system admin)
	// (GET /admin/organizations)
	AdminListOrganizations(ctx context.Context, request AdminListOrganizationsRequestObject) (AdminListOrganizationsResponseObject, error)
	// AdminCreateOrganization Create an organization (system admin)
	// (POST /admin/organizations)
	AdminCreateOrganization(ctx context.Context, request AdminCreateOrganizationRequestObject) (AdminCreateOrganizationResponseObject, error)
	// AdminDeleteOrganization Soft-delete an organization (system admin, ADR-022)
	// (DELETE /admin/organizations/{orgId})
	AdminDeleteOrganization(ctx context.Context, request AdminDeleteOrganizationRequestObject) (AdminDeleteOrganizationResponseObject, error)
	// AdminListUsers All users (system admin)
	// (GET /admin/users)
	AdminListUsers(ctx context.Context, request AdminListUsersRequestObject) (AdminListUsersResponseObject, error)
	// AdminDisableUser Disable a user (soft delete, signs them out everywhere)
	// (POST /admin/users/{userId}/disable)
	AdminDisableUser(ctx context.Context, request AdminDisableUserRequestObject) (AdminDisableUserResponseObject, error)
	// AdminEnableUser Re-enable a disabled user
	// (POST /admin/users/{userId}/enable)
	AdminEnableUser(ctx context.Context, request AdminEnableUserRequestObject) (AdminEnableUserResponseObject, error)
	// AdminCreatePasswordReset Issue a one-time password-reset link (24 h)
	// (POST /admin/users/{userId}/password-reset)
	AdminCreatePasswordReset(ctx context.Context, request AdminCreatePasswordResetRequestObject) (AdminCreatePasswordResetResponseObject, error)
	// AdminResetMfa Remove MFA so the user can enroll again (lost phone and recovery codes)
	// (POST /admin/users/{userId}/reset-mfa)
	AdminResetMfa(ctx context.Context, request AdminResetMfaRequestObject) (AdminResetMfaResponseObject, error)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out and clear the session cookie
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetCurrentSession Current user and CSRF token
	// (GET /auth/me)
	GetCurrentSession(ctx context.Context, request GetCurrentSessionRequestObject) (GetCurrentSessionResponseObject, error)
	// DisableMfa Turn off MFA (not allowed when MFA is mandatory for the account)
	// (POST /auth/mfa/disable)
	DisableMfa(ctx context.Context, request DisableMfaRequestObject) (DisableMfaResponseObject, error)
	// EnableMfa Confirm enrollment with a code; returns one-time recovery codes
	// (POST /auth/mfa/enable)
	EnableMfa(ctx context.Context, request EnableMfaRequestObject) (EnableMfaResponseObject, error)
	// SetupMfa Start TOTP enrollment (returns the secret and a QR code once)
	// (POST /auth/mfa/setup)
	SetupMfa(ctx context.Context, request SetupMfaRequestObject) (SetupMfaResponseObject, error)
	// VerifyMfa Complete sign-in with a TOTP code or a recovery code
	// (POST /auth/mfa/verify)
	VerifyMfa(ctx context.Context, request VerifyMfaRequestObject) (VerifyMfaResponseObject, error)
	// GetHealthz Liveness + database check
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// ListMyOrganizations Organizations the current user belongs to
	// (GET /orgs)
	ListMyOrganizations(ctx context.Context, request ListMyOrganizationsRequestObject) (ListMyOrganizationsResponseObject, error)
	// GetOrganization Organization details and the caller's membership
	// (GET /orgs/{orgId})
	GetOrganization(ctx context.Context, request GetOrganizationRequestObject) (GetOrganizationResponseObject, error)
	// UpdateOrganization Rename / edit notes (owner, admin). Optimistic lock on version.
	// (PATCH /orgs/{orgId})
	UpdateOrganization(ctx context.Context, request UpdateOrganizationRequestObject) (UpdateOrganizationResponseObject, error)
	// ActivateOrganization Remember this organization as the default to open after sign-in
	// (POST /orgs/{orgId}/activate)
	ActivateOrganization(ctx context.Context, request ActivateOrganizationRequestObject) (ActivateOrganizationResponseObject, error)
	// ListOrgAudit Audit log of the organization (owner/admin), newest first
	// (GET /orgs/{orgId}/audit)
	ListOrgAudit(ctx context.Context, request ListOrgAuditRequestObject) (ListOrgAuditResponseObject, error)
	// ListBusinessUnits Business units of the organization, each under a partner (ADR-031)
	// (GET /orgs/{orgId}/business-units)
	ListBusinessUnits(ctx context.Context, request ListBusinessUnitsRequestObject) (ListBusinessUnitsResponseObject, error)
	// CreateBusinessUnit Create a unit under a partner (owner/admin)
	// (POST /orgs/{orgId}/business-units)
	CreateBusinessUnit(ctx context.Context, request CreateBusinessUnitRequestObject) (CreateBusinessUnitResponseObject, error)
	// DeleteBusinessUnit Soft-delete a unit without live sites (owner/admin)
	// (DELETE /orgs/{orgId}/business-units/{businessUnitId})
	DeleteBusinessUnit(ctx context.Context, request DeleteBusinessUnitRequestObject) (DeleteBusinessUnitResponseObject, error)
	// GetBusinessUnit One business unit
	// (GET /orgs/{orgId}/business-units/{businessUnitId})
	GetBusinessUnit(ctx context.Context, request GetBusinessUnitRequestObject) (GetBusinessUnitResponseObject, error)
	// UpdateBusinessUnit Edit a unit (its partner cannot change)
	// (PATCH /orgs/{orgId}/business-units/{businessUnitId})
	UpdateBusinessUnit(ctx context.Context, request UpdateBusinessUnitRequestObject) (UpdateBusinessUnitResponseObject, error)
	// ListMembers Members of the organization
	// (GET /orgs/{orgId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// AddMember Add a member by email (owner/admin/user.manage); unknown emails get a one-time invite link
	// (POST /orgs/{orgId}/members)
	AddMember(ctx context.Context, request AddMemberRequestObject) (AddMemberResponseObject, error)
	// RemoveMember Remove a member from the organization (the last owner cannot be removed)
	// (DELETE /orgs/{orgId}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpdateMember Change role / extra permissions (optimistic lock on version)
	// (PATCH /orgs/{orgId}/members/{userId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// RegenerateInvite Issue a new invite link for a member who has not accepted yet (old links stop working)
	// (POST /orgs/{orgId}/members/{userId}/invite)
	RegenerateInvite(ctx context.Context, request RegenerateInviteRequestObject) (RegenerateInviteResponseObject, error)
	// ListPartners Partners of the organization (ADR-031)
	// (GET /orgs/{orgId}/partners)
	ListPartners(ctx context.Context, request ListPartnersRequestObject) (ListPartnersResponseObject, error)
	// CreatePartner Create a partner (owner/admin)
	// (POST /orgs/{orgId}/partners)
	CreatePartner(ctx context.Context, request CreatePartnerRequestObject) (CreatePartnerResponseObject, error)
	// DeletePartner Soft-delete a partner without live units (owner/admin)
	// (DELETE /orgs/{orgId}/partners/{partnerId})
	DeletePartner(ctx context.Context, request DeletePartnerRequestObject) (DeletePartnerResponseObject, error)
	// GetPartner One partner
	// (GET /orgs/{orgId}/partners/{partnerId})
	GetPartner(ctx context.Context, request GetPartnerRequestObject) (GetPartnerResponseObject, error)
	// UpdatePartner Edit a partner; a code change renames the prefix of its site codes (ADR-030/031)
	// (PATCH /orgs/{orgId}/partners/{partnerId})
	UpdatePartner(ctx context.Context, request UpdatePartnerRequestObject) (UpdatePartnerResponseObject, error)
	// ListSites Sites of the organization (filtered by the member site scope)
	// (GET /orgs/{orgId}/sites)
	ListSites(ctx context.Context, request ListSitesRequestObject) (ListSitesResponseObject, error)
	// CreateSite Create a site (owner/admin/editor without a site scope)
	// (POST /orgs/{orgId}/sites)
	CreateSite(ctx context.Context, request CreateSiteRequestObject) (CreateSiteResponseObject, error)
	// SuggestSiteCode Next free site code for a partner and place (ADR-030/031)
	// (GET /orgs/{orgId}/sites/next-code)
	SuggestSiteCode(ctx context.Context, request SuggestSiteCodeRequestObject) (SuggestSiteCodeResponseObject, error)
	// DeleteSite Soft-delete a site (owner/admin)
	// (DELETE /orgs/{orgId}/sites/{siteId})
	DeleteSite(ctx context.Context, request DeleteSiteRequestObject) (DeleteSiteResponseObject, error)
	// GetSite One site
	// (GET /orgs/{orgId}/sites/{siteId})
	GetSite(ctx context.Context, request GetSiteRequestObject) (GetSiteResponseObject, error)
	// UpdateSite Edit a site (optimistic lock on version)
	// (PATCH /orgs/{orgId}/sites/{siteId})
	UpdateSite(ctx context.Context, request UpdateSiteRequestObject) (UpdateSiteResponseObject, error)
	// ListLocations Location tree of the site as a flat list (parentId links)
	// (GET /orgs/{orgId}/sites/{siteId}/locations)
	ListLocations(ctx context.Context, request ListLocationsRequestObject) (ListLocationsResponseObject, error)
	// CreateLocation Add a building, floor or room
	// (POST /orgs/{orgId}/sites/{siteId}/locations)
	CreateLocation(ctx context.Context, request CreateLocationRequestObject) (CreateLocationResponseObject, error)
	// DeleteLocation Delete an empty location (409 while it has children or racks)
	// (DELETE /orgs/{orgId}/sites/{siteId}/locations/{locationId})
	DeleteLocation(ctx context.Context, request DeleteLocationRequestObject) (DeleteLocationResponseObject, error)
	// UpdateLocation Rename / reorder a location
	// (PATCH /orgs/{orgId}/sites/{siteId}/locations/{locationId})
	UpdateLocation(ctx context.Context, request UpdateLocationRequestObject) (UpdateLocationResponseObject, error)
	// ListRacks Racks of the site
	// (GET /orgs/{orgId}/sites/{siteId}/racks)
	ListRacks(ctx context.Context, request ListRacksRequestObject) (ListRacksResponseObject, error)
	// CreateRack Add a rack to a location of the site
	// (POST /orgs/{orgId}/sites/{siteId}/racks)
	CreateRack(ctx context.Context, request CreateRackRequestObject) (CreateRackResponseObject, error)
	// DeleteRack Delete an empty rack
	// (DELETE /orgs/{orgId}/sites/{siteId}/racks/{rackId})
	DeleteRack(ctx context.Context, request DeleteRackRequestObject) (DeleteRackResponseObject, error)
	// UpdateRack Edit / move a rack within the site
	// (PATCH /orgs/{orgId}/sites/{siteId}/racks/{rackId})
	UpdateRack(ctx context.Context, request UpdateRackRequestObject) (UpdateRackResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// InspectAccountToken operation middleware
func (sh *strictHandler) InspectAccountToken(w http.ResponseWriter, r *http.Request, token string) {
	var request InspectAccountTokenRequestObject

	request.Token = token

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.InspectAccountToken(ctx, request.(InspectAccountTokenRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "InspectAccountToken")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(InspectAccountTokenResponseObject); ok {
		if err := validResponse.VisitInspectAccountTokenResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

